  "scenario_id": "sc-a15166",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2018, 2020],
      "pattern": "shock",
      "direction": "decrease",
      "magnitude": "A/E drops from ~1.20 to a trough of 0.239 in 2019 (~80% below expected), recovering in 2021 to ~1.23",
      "confidence": 0.95,
      "evidence": [
        "ae_ip_by_year.csv shows A/E falling from 1.211 (2017) to 0.814 (2018), 0.239 (2019), 0.357 (2020) before rebounding to 1.232 (2021)",
        "Evidence pack identifies 2019-2020 as a high-score excursion (score 11.1) with onset ratio 0.99, confirming abrupt level change rather than gradual build-up",
        "Poisson z-scores for 2019 (-28.9) and 2020 (-25.3) vastly exceed noise thresholds; empirical YoY SD is x15 Poisson expectation, driven entirely by this excursion"
      ],
      "recommended_action": "Investigate operational, product, or data changes in IP claims reporting/exposure around 2018-2020 (e.g., eligibility changes, claim lag, system migration). Determine if the dip is non-recurring; if confirmed, trim 2019-2020 from pricing/valuation calibration and monitor subsequent years to confirm sustained baseline normalization."
    }
  ]
}

